<script>import {onMount} from 'svelte';import {progress,control} from './store.js';export let execution=null;let value=null,error='';$: if(execution) load(execution.id);async function load(id){try{value=await progress(id)}catch(e){error=e.message}}async function act(action){await control(execution.id,action);await load(execution.id)}</script>
{#if execution}<section><header><div><h2>{execution.workflowName || execution.workflowVersion || execution.id}</h2><p>{execution.id}</p></div><div class="actions"><button on:click={()=>act('pause')}>Pause</button><button on:click={()=>act('resume')}>Resume</button><button on:click={()=>act('cancel')}>Cancel</button></div></header>{#if error}<p class="error">{error}</p>{:else if value}<p>{value.state} · {value.percent}% complete</p><progress max="100" value={value.percent}></progress><div class="steps">{#each value.steps as step (step.id)}<article><strong>{step.name || step.id}</strong><span>{step.state}</span>{#if step.error}<p class="error">{step.error.message || JSON.stringify(step.error)}</p>{/if}</article>{/each}</div>{:else}<p>Loading execution…</p>{/if}</section>{:else}<p>Select a workflow execution.</p>{/if}<style>header{display:flex;justify-content:space-between;gap:12px}h2{margin:0}p{color:#697586}.actions{display:flex;gap:6px}.actions button,button{padding:8px 10px;border:1px solid #cbd5e1;background:#fff;border-radius:5px;cursor:pointer}.steps{display:grid;gap:8px;margin-top:16px}.steps article{display:flex;justify-content:space-between;gap:12px;border:1px solid #e2e8f0;border-radius:6px;padding:10px}.steps p{display:block}.error{color:#b42318}progress{width:100%}</style>
